    'setup_start("TensorFlow backend")\n'
    'if not RUNNING_IN_COLAB:\n'
    '    # On local Jupyter/HPC environments, pip-installed nvidia-* packages put CUDA\n'
    '    # libraries inside site-packages/nvidia/*/lib/ instead of a system path.\n'
    '    # TF cannot dlopen them unless these directories are on LD_LIBRARY_PATH.\n'
    '    # Colab manages its own CUDA paths, so we skip this there.\n'
    '    try:\n'
    '        def _patch_nvidia_ld_path():\n'
    '            import site\n'
    '            sp = next((p for p in site.getsitepackages() if "site-packages" in p), None)\n'
    '            if not sp:\n'
    '                return\n'
    '            nvidia_base = os.path.join(sp, "nvidia")\n'
    '            subdirs = [\n'
    '                "cublas", "cuda_cupti", "cuda_nvrtc", "cuda_runtime",\n'
    '                "cudnn", "cufft", "curand", "cusolver", "cusparse",\n'
    '                "nccl", "nvjitlink", "nvtx",\n'
    '            ]\n'
    '            extra = ":".join(\n'
    '                os.path.join(nvidia_base, s, "lib")\n'
    '                for s in subdirs\n'
    '                if os.path.isdir(os.path.join(nvidia_base, s, "lib"))\n'
    '            )\n'
    '            if extra:\n'
    '                prev = os.environ.get("LD_LIBRARY_PATH", "")\n'
    '                os.environ["LD_LIBRARY_PATH"] = f"{extra}:{prev}" if prev else extra\n'
    '        _patch_nvidia_ld_path()\n'
    '        del _patch_nvidia_ld_path\n'
    '    except Exception:\n'
    '        pass\n'
    'try:\n'
    '    import tensorflow as tf\n'
    '    if not RUNNING_IN_COLAB and tf.config.list_physical_devices("GPU"):\n'
    '        # Probe graph-function mode before committing TF to GPU.\n'
    '        # NVIDIA GRID vGPU raises CUDA_ERROR_INVALID_HANDLE on graph-mode\n'
    '        # kernel launches (e.g. FloorMod during Keras layer seeding).\n'
    '        # A bare-metal GPU passes this probe and keeps GPU enabled;\n'
    '        # a restricted vGPU fails and falls back to CPU-only.\n'
    '        # PyTorch manages its own CUDA context independently.\n'
    '        try:\n'
    '            @tf.function\n'
    '            def _tf_gpu_probe():\n'
    '                return tf.math.floormod(tf.constant(5), tf.constant(3))\n'
    '            _tf_gpu_probe()\n'
    '            del _tf_gpu_probe\n'
    '        except Exception:\n'
    '            tf.config.set_visible_devices([], "GPU")\n'
    'except Exception:\n'
