    'setup_start("Resource detection")\n'
    '\n'
    'def detected_cpu_count():\n'
    '    return max(1, int(os.cpu_count() or 1))\n'
    '\n'
    'def qsarena_n_jobs(value=0):\n'
    '    try:\n'
    '        requested = int(value)\n'
    '    except Exception:\n'
    '        requested = 0\n'
    '    if requested <= 0:\n'
    '        return detected_cpu_count()\n'
    '    return max(1, requested)\n'
    '\n'
    'def auto_data_loader_workers():\n'
    '    cpu_count = detected_cpu_count()\n'
    '    return max(1, min(8, cpu_count // 4 if cpu_count >= 4 else 1))\n'
    '\n'
    'def resolve_auto_worker_count(value):\n'
    '    try:\n'
    '        requested = int(value)\n'
    '    except Exception:\n'
    '        requested = 0\n'
    '    if requested <= 0:\n'
    '        return auto_data_loader_workers()\n'
    '    return max(0, requested)\n'
    '\n'
    'def gpu_inventory():\n'
    '    if torch is None:\n'
    '        return []\n'
    '    try:\n'
    '        if not bool(torch.cuda.is_available()):\n'
    '            return []\n'
    '        rows = []\n'
    '        for index in range(int(torch.cuda.device_count())):\n'
    '            props = torch.cuda.get_device_properties(index)\n'
    '            rows.append(\n'
    '                {\n'
    '                    "index": int(index),\n'
    '                    "name": str(torch.cuda.get_device_name(index)),\n'
    '                    "total_memory_gb": round(float(props.total_memory) / (1024 ** 3), 3),\n'
    '                    "multi_processor_count": int(getattr(props, "multi_processor_count", 0)),\n'
    '                    "compute_capability": f"{getattr(props, \'major\', \'\')}.{getattr(props, \'minor\', \'\')}",\n'
    '                }\n'
    '            )\n'
    '        return rows\n'
    '    except Exception:\n'
    '        return []\n'
    '\n'
    'def torch_gpu_available():\n'
    '    # Uni-Mol and Chemprop run on PyTorch, so they need a CUDA device that PyTorch can see; a\n'
    '    # TensorFlow-only GPU does not count. Checked live, because the Colab runtime type can change.\n'
    '    try:\n'
    '        return bool(torch is not None and torch.cuda.is_available())\n'
    '    except Exception:\n'
    '        return False\n'
    '\n'
    'unimol_gpu_available = torch_gpu_available\n'
    '\n'
    'def refresh_resource_config():\n'
    '    torch_gpu = bool(torch is not None and torch.cuda.is_available())\n'
    '    tf_gpus = [] if tf is None else tf.config.list_physical_devices("GPU")\n'
    '    tf_gpu = len(tf_gpus) > 0\n'
    '    resource_config = {\n'
    '        "detected_cpu_count": detected_cpu_count(),\n'
    '        "n_jobs": qsarena_n_jobs(),\n'
    '        "auto_data_loader_workers": auto_data_loader_workers(),\n'
    '        "torch_gpu_available": bool(torch_gpu),\n'
    '        "tensorflow_gpu_count": int(len(tf_gpus)),\n'
    '        "gpu_available": bool(torch_gpu or tf_gpu),\n'
    '        "gpu_inventory": gpu_inventory(),\n'
    '    }\n'
    '    STATE["resource_config"] = dict(resource_config)\n'
