    'def slugify_cache_text(value):\n'
    '    text = str(value).strip()\n'
    '    text = re.sub(r"[^A-Za-z0-9._-]+", "_", text)\n'
    '    text = re.sub(r"_+", "_", text).strip("._")\n'
    '    return text or "artifact"\n'
    '\n'
    'def current_dataset_cache_label():\n'
    '    benchmark_meta = STATE.get("benchmark_metadata") or {}\n'
    '    benchmark_dataset_name = str(benchmark_meta.get("dataset_name", "")).strip()\n'
    '    if benchmark_dataset_name:\n'
    '        return slugify_cache_text(benchmark_dataset_name)\n'
    '    label = STATE.get("data_source_label") or STATE.get("uploaded_filename") or "dataset"\n'
    '    try:\n'
    '        return slugify_cache_text(Path(str(label)).stem)\n'
    '    except Exception:\n'
    '        return slugify_cache_text(label)\n'
    '\n'
    'def resolve_output_path(path_text):\n'
    '    candidate = Path(str(path_text))\n'
    '    if candidate.is_absolute():\n'
    '        return candidate\n'
    '    root = Path(STATE.get("persistent_output_root", ".")).expanduser()\n'
    '    return (root / candidate).resolve()\n'
    '\n'
    'def resolve_model_cache_dir(workflow_key, run_name="AUTO", prefer_existing=False):\n'
    '    workflow_slug = slugify_cache_text(workflow_key)\n'
    '    model_cache_root = resolve_output_path("model_cache")\n'
    '    run_text = str(run_name).strip()\n'
    '    if run_text and run_text.upper() != "AUTO":\n'
    '        run_slug = slugify_cache_text(run_text)\n'
    '    else:\n'
    '        workflow_root = model_cache_root / workflow_slug\n'
    '        dataset_suffix = f"_{current_dataset_cache_label()}_{workflow_slug}"\n'
    '        if prefer_existing and workflow_root.exists():\n'
    '            existing = sorted(\n'
    '                [\n'
    '                    path\n'
    '                    for path in workflow_root.iterdir()\n'
    '                    if path.is_dir() and path.name.endswith(dataset_suffix)\n'
    '                ],\n'
    '                key=lambda path: path.name,\n'
    '                reverse=True,\n'
    '            )\n'
    '            if existing:\n'
    '                existing[0].mkdir(parents=True, exist_ok=True)\n'
    '                return existing[0]\n'
    '        run_slug = (\n'
    '            f"{STATE.get(\'cache_session_stamp\', time.strftime(\'%Y%m%d_%H%M%S\'))}_"\n'
    '            f"{current_dataset_cache_label()}_{workflow_slug}"\n'
    '        )\n'
    '    cache_dir = model_cache_root / workflow_slug / run_slug\n'
    '    cache_dir.mkdir(parents=True, exist_ok=True)\n'
    '    return cache_dir\n'
    '\n'
    'def write_cache_metadata(path, metadata):\n'
    '    import json\n'
    '\n'
    '    serializable = {}\n'
    '    for key, value in metadata.items():\n'
    '        if isinstance(value, (str, int, float, bool)) or value is None:\n'
    '            serializable[key] = value\n'
    '        else:\n'
    '            serializable[key] = str(value)\n'
    '    path.write_text(json.dumps(serializable, indent=2), encoding="utf-8")\n'
    '\n'
    'def read_cache_metadata(path):\n'
    '    import json\n'
    '\n'
    '    return json.loads(Path(path).read_text(encoding="utf-8"))\n'
    '\n'
    'def resolve_cached_artifact_path(path_value, metadata_path):\n'
    '    candidate = Path(str(path_value))\n'
    '    metadata_dir = Path(metadata_path).parent\n'
    '    if candidate.exists():\n'
    '        return candidate\n'
    '    sibling_candidate = metadata_dir / candidate.name\n'
    '    if sibling_candidate.exists():\n'
    '        return sibling_candidate\n'
    '    recursive_matches = sorted(metadata_dir.rglob(candidate.name), key=lambda path: len(str(path)))\n'
    '    if recursive_matches:\n'
    '        return recursive_matches[0]\n'
    '    return candidate\n'
    '\n'
    'def cache_metadata_matches(metadata, expected):\n'
    '    for key, expected_value in expected.items():\n'
    '        if expected_value is None:\n'
    '            continue\n'
    '        if str(metadata.get(key)) != str(expected_value):\n'
    '            return False\n'
    '    return True\n'
    '\n'
    'def _normalize_smiles_series(values):\n'
    '    return pd.Series(values, dtype=str).astype(str).str.strip().reset_index(drop=True)\n'
    '\n'
    'def build_split_signature(train_smiles, test_smiles):\n'
    '    import hashlib\n'
    '\n'
    '    train_series = _normalize_smiles_series(train_smiles)\n'
    '    test_series = _normalize_smiles_series(test_smiles)\n'
    '\n'
    '    if train_series.empty or test_series.empty:\n'
    '        raise ValueError(\n'
    '            "Split signature guard cannot run on an empty split. "\n'
    '            f"Received train={len(train_series)}, test={len(test_series)}."\n'
    '        )\n'
    '    if train_series.duplicated().any():\n'
    '        raise ValueError("Split signature guard requires unique training SMILES, but duplicates were found.")\n'
    '    if test_series.duplicated().any():\n'
    '        raise ValueError("Split signature guard requires unique test SMILES, but duplicates were found.")\n'
    '\n'
    '    train_set = set(train_series.tolist())\n'
    '    test_set = set(test_series.tolist())\n'
    '    overlap = sorted(train_set.intersection(test_set))\n'
    '    if overlap:\n'
    '        overlap_preview = ", ".join(overlap[:3])\n'
    '        raise ValueError(\n'
    '            "Split signature guard requires disjoint train/test SMILES, "\n'
    '            f"but found {len(overlap)} overlap(s): {overlap_preview}."\n'
    '        )\n'
    '\n'
    '    def _hash_smiles_set(smiles_set):\n'
    '        digest = hashlib.sha256()\n'
    '        for item in sorted(smiles_set):\n'
    '            digest.update(item.encode("utf-8"))\n'
    '            digest.update(b"\\n")\n'
    '        return digest.hexdigest()\n'
    '\n'
    '    return {\n'
    '        "train_count": int(len(train_series)),\n'
    '        "test_count": int(len(test_series)),\n'
    '        "train_hash": _hash_smiles_set(train_set),\n'
    '        "test_hash": _hash_smiles_set(test_set),\n'
    '    }\n'
    '\n'
    'def ensure_global_split_signature(train_smiles, test_smiles, source_label="unknown"):\n'
    '    signature = build_split_signature(train_smiles, test_smiles)\n'
    '    dataset_label = current_dataset_cache_label()\n'
    '    canonical_signature = STATE.get("canonical_split_signature")\n'
    '    canonical_dataset_label = STATE.get("canonical_split_dataset_label")\n'
    '    canonical_source = STATE.get("canonical_split_source", "unknown")\n'
    '\n'
    '    if canonical_signature is None or str(canonical_dataset_label) != str(dataset_label):\n'
    '        STATE["canonical_split_signature"] = dict(signature)\n'
    '        STATE["canonical_split_dataset_label"] = str(dataset_label)\n'
    '        STATE["canonical_split_source"] = str(source_label)\n'
    '        print(\n'
    '            "Canonical split signature established: "\n'
    '            f"dataset={dataset_label}, source={source_label}, "\n'
    '            f"train={signature[\'train_count\']}, test={signature[\'test_count\']}",\n'
    '            flush=True,\n'
    '        )\n'
    '        return dict(signature)\n'
    '\n'
    '    mismatch_fields = []\n'
    '    for key in ["train_count", "test_count", "train_hash", "test_hash"]:\n'
    '        if str(canonical_signature.get(key)) != str(signature.get(key)):\n'
    '            mismatch_fields.append(key)\n'
    '\n'
    '    if mismatch_fields:\n'
    '        raise RuntimeError(\n'
    '            "Global split signature guard violation: train/test SMILES do not match the canonical split for this dataset.\\n"\n'
    '            f"Dataset label: {dataset_label}\\n"\n'
    '            f"Canonical source: {canonical_source}\\n"\n'
    '            f"Current source: {source_label}\\n"\n'
    '            f"Mismatched fields: {\', \'.join(mismatch_fields)}\\n"\n'
    '            f"Canonical counts (train/test): {canonical_signature.get(\'train_count\')}/{canonical_signature.get(\'test_count\')}\\n"\n'
    '            f"Current counts (train/test): {signature.get(\'train_count\')}/{signature.get(\'test_count\')}\\n"\n'
    '            "Rerun from step 0 and keep identical split settings across workflows. "\n'
    '            "If using Uni-Mol, disable subset/filter options that change split membership."\n'
    '        )\n'
    '\n'
    '    return dict(signature)\n'
    '\n'
    'def dataframe_cache_signature(frame, max_rows=None):\n'
    '    import hashlib\n'
    '\n'
    '    working = frame.copy()\n'
    '    if max_rows is not None and len(working) > int(max_rows):\n'
    '        working = working.iloc[: int(max_rows)].copy()\n'
    '    hashed = pd.util.hash_pandas_object(working, index=True).to_numpy(dtype=np.uint64)\n'
    '    digest = hashlib.sha256()\n'
    '    digest.update(np.asarray(hashed, dtype=np.uint64).tobytes())\n'
    '    digest.update("|".join(map(str, working.columns)).encode("utf-8"))\n'
    '    digest.update(str(tuple(working.shape)).encode("utf-8"))\n'
    '    return digest.hexdigest()\n'
    '\n'
    'def array_cache_signature(values):\n'
    '    import hashlib\n'
    '\n'
    '    arr = np.asarray(values, dtype=float).reshape(-1)\n'
    '    digest = hashlib.sha256()\n'
    '    digest.update(np.nan_to_num(arr, nan=1.23456789e308, posinf=9.87654321e307, neginf=-9.87654321e307).tobytes())\n'
    '    digest.update(str(arr.shape).encode("utf-8"))\n'
    '    return digest.hexdigest()\n'
    '\n'
    'def write_ga_state(path, population, fitness_dict):\n'
    '    import json\n'
    '\n'
    '    serialized = {\n'
    '        "population": [list(individual) for individual in (population or [])],\n'
    '        "fitness_dict": [\n'
    '            {\n'
    '                "individual": list(individual),\n'
    '                "fitness": list(fitness),\n'
    '            }\n'
    '            for individual, fitness in (fitness_dict or {}).items()\n'
    '        ],\n'
    '    }\n'
    '    Path(path).write_text(json.dumps(serialized, indent=2), encoding="utf-8")\n'
    '\n'
    'def read_ga_state(path):\n'
    '    import json\n'
    '\n'
    '    payload = json.loads(Path(path).read_text(encoding="utf-8"))\n'
    '    population = [tuple(individual) for individual in payload.get("population", [])]\n'
    '    fitness_dict = {\n'
    '        tuple(item["individual"]): tuple(item["fitness"])\n'
    '        for item in payload.get("fitness_dict", [])\n'
    '    }\n'
    '    return {\n'
    '        "population": population,\n'
    '        "fitness_dict": fitness_dict,\n'
    '    }\n'
    '\n'
    'def extract_ga_fitness_scalar(value):\n'
    '    import ast\n'
    '    import re\n'
    '\n'
    '    if value is None:\n'
    '        return np.nan\n'
    '    if isinstance(value, (tuple, list, np.ndarray)):\n'
    '        if len(value) == 0:\n'
    '            return np.nan\n'
    '        return float(value[0])\n'
    '    if isinstance(value, str):\n'
    '        text = value.strip()\n'
    '        if not text:\n'
    '            return np.nan\n'
    '        try:\n'
    '            parsed = ast.literal_eval(text)\n'
    '        except Exception:\n'
    '            parsed = None\n'
    '        if isinstance(parsed, (tuple, list, np.ndarray)):\n'
    '            if len(parsed) == 0:\n'
    '                return np.nan\n'
    '            return float(parsed[0])\n'
    '        if parsed is not None:\n'
    '            return float(parsed)\n'
    '        numeric_match = re.search(r"[-+]?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)(?:[eE][-+]?[0-9]+)?", text)\n'
    '        if numeric_match:\n'
    '            return float(numeric_match.group(0))\n'
    '        raise ValueError(f"Could not parse GA fitness value: {value!r}")\n'
    '    return float(value)\n'
    '\n'
    'def load_prediction_splits(prediction_path, train_smiles, test_smiles, allow_reorder=False):\n'
    '    prediction_df = pd.read_csv(prediction_path)\n'
    '    if "split" not in prediction_df.columns:\n'
    '        raise ValueError("Cached prediction file is missing the \'split\' column.")\n'
    '\n'
    '    train_frame = prediction_df.loc[prediction_df["split"].astype(str) == "train"].reset_index(drop=True)\n'
    '    test_frame = prediction_df.loc[prediction_df["split"].astype(str) == "test"].reset_index(drop=True)\n'
    '    expected_train_smiles = pd.Series(train_smiles, dtype=str).reset_index(drop=True)\n'
    '    expected_test_smiles = pd.Series(test_smiles, dtype=str).reset_index(drop=True)\n'
    '\n'
    '    if len(train_frame) != len(expected_train_smiles) or len(test_frame) != len(expected_test_smiles):\n'
    '        raise ValueError("Cached prediction lengths do not match the current train/test split.")\n'
    '\n'
    '    train_smiles_cached = train_frame["smiles"].astype(str).reset_index(drop=True)\n'
    '    test_smiles_cached = test_frame["smiles"].astype(str).reset_index(drop=True)\n'
    '    train_exact_match = train_smiles_cached.equals(expected_train_smiles)\n'
    '    test_exact_match = test_smiles_cached.equals(expected_test_smiles)\n'
    '\n'
    '    if not (train_exact_match and test_exact_match):\n'
    '        if not allow_reorder:\n'
    '            if not train_exact_match:\n'
    '                raise ValueError("Cached training predictions do not match the current train split.")\n'
    '            raise ValueError("Cached test predictions do not match the current test split.")\n'
    '\n'
    '        def _reorder_split_frame(frame, expected_smiles, split_label):\n'
    '            expected_smiles = pd.Series(expected_smiles, dtype=str).reset_index(drop=True)\n'
    '            frame = frame.copy()\n'
    '            frame["smiles"] = frame["smiles"].astype(str).reset_index(drop=True)\n'
    '            if frame["smiles"].duplicated().any():\n'
    '                raise ValueError(\n'
    '                    f"Cached {split_label} predictions contain duplicate SMILES; cannot safely reorder."\n'
    '                )\n'
    '            if expected_smiles.duplicated().any():\n'
    '                raise ValueError(\n'
    '                    f"Current {split_label} split contains duplicate SMILES; cannot safely reorder cached predictions."\n'
    '                )\n'
    '            frame_indexed = frame.set_index("smiles", drop=False)\n'
    '            expected_set = set(expected_smiles.tolist())\n'
    '            cached_set = set(frame_indexed.index.tolist())\n'
    '            if expected_set != cached_set:\n'
    '                missing = sorted(expected_set - cached_set)\n'
    '                extra = sorted(cached_set - expected_set)\n'
    '                missing_preview = ", ".join(missing[:3]) if missing else "none"\n'
    '                extra_preview = ", ".join(extra[:3]) if extra else "none"\n'
    '                raise ValueError(\n'
    '                    f"Cached {split_label} SMILES set does not match current split "\n'
    '                    f"(missing={len(missing)} [{missing_preview}], extra={len(extra)} [{extra_preview}])."\n'
    '                )\n'
    '            return frame_indexed.loc[expected_smiles.tolist()].reset_index(drop=True)\n'
    '\n'
    '        train_frame = _reorder_split_frame(train_frame, expected_train_smiles, "train")\n'
    '        test_frame = _reorder_split_frame(test_frame, expected_test_smiles, "test")\n'
    '\n'
    '    return {\n'
    '        "train": train_frame,\n'
    '        "test": test_frame,\n'
    '    }\n'
    '\n'
    'setup_start("QSARena shared workflow core")\n'
    'ensure_qsarena_bundle_source()\n'
