    'def apply_qsar_split(split_strategy="random", test_fraction=0.2, random_seed=42, announce=True):\n'
    '    if "feature_matrix" not in STATE:\n'
    '        raise RuntimeError("Please build the molecular feature matrix first.")\n'
    '\n'
    '    X = STATE["feature_matrix"].copy()\n'
    '    y = STATE["curated_df"]["target"].astype(float).reset_index(drop=True)\n'
    '    smiles = STATE["curated_df"]["canonical_smiles"].astype(str).reset_index(drop=True)\n'
    '\n'
    '    split_strategy = str(split_strategy).strip().lower()\n'
    '    if split_strategy not in {"random", "scaffold", "target_quartiles", "predefined"}:\n'
    '        raise ValueError("Split strategy must be \'random\', \'scaffold\', \'target_quartiles\', or \'predefined\'.")\n'
    '\n'
    '    if split_strategy == "predefined":\n'
    '        split_labels = STATE.get("predefined_split_labels")\n'
    '        if split_labels is None:\n'
    '            raise ValueError(\n'
    '                "Split strategy `predefined` requires predefined split labels from the loaded benchmark dataset."\n'
    '            )\n'
    '        split_labels = (\n'
    '            pd.Series(split_labels, dtype=str)\n'
    '            .str.strip()\n'
    '            .str.lower()\n'
    '            .reset_index(drop=True)\n'
    '        )\n'
    '        if len(split_labels) != len(X):\n'
    '            raise ValueError(\n'
    '                "Predefined split labels length does not match the current curated dataset length. "\n'
    '                "Rerun from step 1A and keep benchmark split labels in sync."\n'
    '            )\n'
    '        train_mask = split_labels == "train"\n'
    '        test_mask = split_labels == "test"\n'
    '        if int(train_mask.sum()) == 0 or int(test_mask.sum()) == 0:\n'
    '            raise ValueError(\n'
    '                "Predefined split labels must contain both train and test rows after curation."\n'
    '            )\n'
    '        X_train = X.loc[train_mask].reset_index(drop=True)\n'
    '        X_test = X.loc[test_mask].reset_index(drop=True)\n'
    '        y_train = y.loc[train_mask].reset_index(drop=True)\n'
    '        y_test = y.loc[test_mask].reset_index(drop=True)\n'
    '        smiles_train = smiles.loc[train_mask].reset_index(drop=True)\n'
    '        smiles_test = smiles.loc[test_mask].reset_index(drop=True)\n'
    '        test_fraction = float(len(X_test) / max(1, len(X)))\n'
    '    elif split_strategy in {"random", "target_quartiles"}:\n'
    '        stratify_labels = None\n'
    '        if split_strategy == "target_quartiles":\n'
    '            # A binary target has no quartiles: stratify on the class labels instead.\n'
    '            stratify_labels = (\n'
    '                pd.Series(y, dtype=float).round().astype(int).astype(str)\n'
    '                if task_is_classification()\n'
    '                else target_quartile_labels(y, q=4)\n'
    '            )\n'
    '        X_train, X_test, y_train, y_test, smiles_train, smiles_test = train_test_split(\n'
    '            X,\n'
    '            y,\n'
    '            smiles,\n'
    '            test_size=float(test_fraction),\n'
    '            random_state=int(random_seed),\n'
    '            stratify=stratify_labels,\n'
    '        )\n'
    '        X_train = X_train.reset_index(drop=True)\n'
