    'setup_start("runtime estimate helper")\n'
    'TABLE6_REFERENCE_ROWS = 1605.0\n'
    'TABLE6_MEDIAN_SECONDS = {\n'
    '    "conventional_model": 6.8,\n'
    '    "chemml_mlp": 39.8,\n'
    '    "maplight_gnn": 137.4,\n'
    '    "chemprop_variant": 268.6,\n'
    '    "unimol_model": 373.5,\n'
    '}\n'
    '\n'
    'def format_runtime_estimate(seconds):\n'
    '    seconds = float(seconds)\n'
    '    if not math.isfinite(seconds):\n'
    '        return "unknown"\n'
    '    seconds = max(0.0, seconds)\n'
    '    if seconds < 90:\n'
    '        return f"{seconds:.0f} sec"\n'
    '    if seconds < 5400:\n'
    '        return f"{seconds / 60.0:.0f} min"\n'
    '    if seconds < 172800:\n'
    '        return f"{seconds / 3600.0:.1f} hr"\n'
    '    return f"{seconds / 86400.0:.1f} days"\n'
    '\n'
    'def estimate_table6_seconds(kind, n_rows, *, gpu_available=False, multiplier=1.0):\n'
    '    scale = max(0.05, float(n_rows) / TABLE6_REFERENCE_ROWS)\n'
    '    seconds = TABLE6_MEDIAN_SECONDS[kind] * scale * float(multiplier)\n'
    '    if not gpu_available and kind in {"chemml_mlp", "maplight_gnn"}:\n'
    '        seconds *= 2.0\n'
    '    if not gpu_available and kind in {"chemprop_variant", "unimol_model"}:\n'
    '        seconds *= 8.0\n'
    '    return float(seconds)\n'
    '\n'
    'def estimate_elasticnet_selector_seconds(n_rows):\n'
    '    n_train = max(2.0, 0.8 * float(n_rows))\n'
    '    predicted = 10 ** (-0.658 + 1.225 * math.log10(n_train))\n'
    '    return min(float(predicted), 7200.0)\n'
    '\n'
    'def notebook_runtime_estimate_rows(n_rows):\n'
    '    gpu_available = bool(gpu_inventory())\n'
    '    n_rows = int(n_rows)\n'
    '    feature_seconds = 5.0 + 0.02 * float(n_rows)\n'
