    'setup_start("SMILES curation helper")\n'
    'def curate_smiles_dataframe(\n'
    '    df,\n'
    '    smiles_col,\n'
    '    target_col,\n'
    '    aux_columns=None,\n'
    '    deduplicate=True,\n'
    '    strict_consistency_columns=None,\n'
    '):\n'
    '    aux_columns = [col for col in (aux_columns or []) if col in df.columns and col not in {smiles_col, target_col}]\n'
    '    strict_consistency_columns = [\n'
    '        col for col in (strict_consistency_columns or [])\n'
    '        if col in aux_columns\n'
    '    ]\n'
    '    temp = df[[smiles_col, target_col] + aux_columns].copy()\n'
    '    temp = temp.rename(columns={smiles_col: "raw_smiles", target_col: "target"})\n'
    '    temp["target"] = pd.to_numeric(temp["target"], errors="coerce")\n'
    '    temp["raw_smiles"] = temp["raw_smiles"].astype(str).str.strip()\n'
    '    stats = {"rows_before": int(len(temp))}\n'
    '    before_drop = len(temp)\n'
    '    temp = temp.replace({"raw_smiles": {"": np.nan, "nan": np.nan, "None": np.nan}})\n'
    '    temp = temp.dropna(subset=["raw_smiles", "target"]).copy()\n'
    '    stats["missing_rows_removed"] = int(before_drop - len(temp))\n'
    '    canonical, mols, invalid = [], [], 0\n'
    '    for smi in temp["raw_smiles"]:\n'
    '        mol = Chem.MolFromSmiles(smi)\n'
    '        if mol is None:\n'
    '            canonical.append(None)\n'
    '            mols.append(None)\n'
    '            invalid += 1\n'
    '        else:\n'
    '            canonical.append(Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True))\n'
    '            mols.append(mol)\n'
    '    temp["canonical_smiles"] = canonical\n'
    '    temp["rdkit_mol"] = mols\n'
    '    temp = temp.dropna(subset=["canonical_smiles"]).copy()\n'
    '    stats["invalid_smiles_removed"] = int(invalid)\n'
    '    before_dedup = len(temp)\n'
    '    if deduplicate:\n'
    '        for col in strict_consistency_columns:\n'
    '            inconsistent_mask = (\n'
    '                temp.groupby("canonical_smiles")[col]\n'
    '                .nunique(dropna=False)\n'
    '                .gt(1)\n'
    '            )\n'
    '            if bool(inconsistent_mask.any()):\n'
    '                conflicting = inconsistent_mask[inconsistent_mask].index.tolist()\n'
    '                preview = ", ".join([str(item) for item in conflicting[:3]])\n'
    '                raise ValueError(\n'
    '                    f"Found conflicting `{col}` labels for {len(conflicting)} canonical SMILES after curation "\n'
    '                    f"(examples: {preview}). Disable duplicate collapsing or use a split-consistent dataset."\n'
    '                )\n'
    '\n'
    '        def _first_nonnull(series):\n'
    '            series = series.dropna()\n'
    '            if series.empty:\n'
    '                return np.nan\n'
    '            return series.iloc[0]\n'
    '\n'
    '        agg_map = {"target": "mean"}\n'
    '        for col in aux_columns:\n'
    '            agg_map[col] = _first_nonnull\n'
    '        temp = temp.groupby("canonical_smiles", as_index=False).agg(agg_map)\n'
    '        temp["rdkit_mol"] = temp["canonical_smiles"].map(Chem.MolFromSmiles)\n'
    '    stats["duplicate_canonical_smiles_collapsed"] = int(before_dedup - len(temp))\n'
    '    stats["aux_columns_retained"] = int(len(aux_columns))\n'
    '    return temp.reset_index(drop=True), stats\n'
    'setup_done("SMILES curation helper")\n'
    '\n'
    'setup_start("auxiliary feature helper")\n'
    'def build_auxiliary_feature_matrix(df, aux_columns):\n'
    '    aux_columns = [col for col in (aux_columns or []) if col in df.columns]\n'
    '    if not aux_columns:\n'
    '        return pd.DataFrame(index=df.index)\n'
    '\n'
    '    aux_df = df[aux_columns].copy()\n'
    '    numeric_cols = []\n'
    '    categorical_cols = []\n'
    '    for col in aux_columns:\n'
    '        series = aux_df[col]\n'
    '        non_null = series.notna().sum()\n'
    '        numeric_series = pd.to_numeric(series, errors="coerce")\n'
    '        numeric_non_null = numeric_series.notna().sum()\n'
    '        if non_null > 0 and numeric_non_null >= max(1, int(0.7 * non_null)):\n'
    '            aux_df[col] = numeric_series\n'
    '            numeric_cols.append(col)\n'
    '        else:\n'
    '            categorical_cols.append(col)\n'
    '\n'
    '    numeric_frame = pd.DataFrame(index=aux_df.index)\n'
    '    if numeric_cols:\n'
    '        numeric_frame = aux_df[numeric_cols].copy()\n'
    '        for col in numeric_cols:\n'
    '            median = numeric_frame[col].median()\n'
    '            if pd.isna(median):\n'
    '                median = 0.0\n'
    '            numeric_frame[col] = numeric_frame[col].fillna(median).astype(float)\n'
    '        numeric_frame = numeric_frame.rename(columns={col: f"aux_{col}" for col in numeric_cols})\n'
    '\n'
    '    categorical_frame = pd.DataFrame(index=aux_df.index)\n'
    '    if categorical_cols:\n'
    '        cat_base = aux_df[categorical_cols].copy()\n'
    '        for col in categorical_cols:\n'
    '            cat_base[col] = cat_base[col].astype(str).fillna("Unknown")\n'
    '        categorical_frame = pd.get_dummies(\n'
    '            cat_base,\n'
    '            prefix=[f"aux_{col}" for col in categorical_cols],\n'
    '            prefix_sep="=",\n'
    '            dummy_na=False,\n'
    '        )\n'
    '\n'
    '    combined = pd.concat([numeric_frame, categorical_frame], axis=1)\n'
    '    combined = combined.reindex(sorted(combined.columns), axis=1)\n'
    '    return combined.reset_index(drop=True)\n'
    '\n'
    'def build_auxiliary_features_for_smiles(smiles_values, aux_columns):\n'
    '    smiles_series = pd.Series(smiles_values, dtype=str).reset_index(drop=True)\n'
    '    aux_columns = [col for col in (aux_columns or [])]\n'
    '    if not aux_columns or "curated_df" not in STATE:\n'
    '        return pd.DataFrame(index=smiles_series.index)\n'
    '    curated = STATE["curated_df"].copy()\n'
    '    available_aux = [col for col in aux_columns if col in curated.columns]\n'
    '    if not available_aux:\n'
    '        return pd.DataFrame(index=smiles_series.index)\n'
    '    lookup = (\n'
    '        curated[["canonical_smiles"] + available_aux]\n'
    '        .drop_duplicates(subset=["canonical_smiles"], keep="first")\n'
    '        .set_index("canonical_smiles")\n'
    '    )\n'
    '    ordered = lookup.reindex(smiles_series.tolist()).reset_index(drop=True)\n'
    '    return build_auxiliary_feature_matrix(ordered, available_aux)\n'
    '\n'
    'def fit_auxiliary_fusion_head(\n'
    '    base_train_predictions,\n'
    '    base_test_predictions,\n'
    '    y_train_values,\n'
    '    train_smiles,\n'
    '    test_smiles,\n'
    '    random_seed=42,\n'
    '    label=None,\n'
    '):\n'
    '    aux_columns = list(STATE.get("auxiliary_columns", []))\n'
    '    if not aux_columns:\n'
    '        return np.asarray(base_train_predictions, dtype=float), np.asarray(base_test_predictions, dtype=float), None\n'
    '\n'
    '    train_aux = build_auxiliary_features_for_smiles(train_smiles, aux_columns)\n'
    '    test_aux_raw = build_auxiliary_features_for_smiles(test_smiles, aux_columns)\n'
    '    if train_aux.empty:\n'
    '        return np.asarray(base_train_predictions, dtype=float), np.asarray(base_test_predictions, dtype=float), None\n'
    '\n'
    '    train_aux = align_feature_matrix_to_training_columns(train_aux, list(train_aux.columns))\n'
    '    test_aux = align_feature_matrix_to_training_columns(test_aux_raw, list(train_aux.columns))\n'
    '\n'
    '    fusion_train = pd.concat(\n'
    '        [\n'
    '            pd.DataFrame({"base_prediction": np.asarray(base_train_predictions, dtype=float)}),\n'
    '            train_aux.reset_index(drop=True),\n'
    '        ],\n'
    '        axis=1,\n'
    '    )\n'
    '    fusion_test = pd.concat(\n'
    '        [\n'
    '            pd.DataFrame({"base_prediction": np.asarray(base_test_predictions, dtype=float)}),\n'
    '            test_aux.reset_index(drop=True),\n'
    '        ],\n'
    '        axis=1,\n'
    '    )\n'
    '\n'
    '    fusion_model = ElasticNet(\n'
    '        alpha=0.001,\n'
    '        l1_ratio=0.5,\n'
    '        max_iter=20000,\n'
    '        random_state=int(random_seed),\n'
    '    )\n'
    '    fusion_model.fit(fusion_train.to_numpy(dtype=float), np.asarray(y_train_values, dtype=float))\n'
    '    fused_train = np.asarray(fusion_model.predict(fusion_train.to_numpy(dtype=float)), dtype=float).reshape(-1)\n'
    '    fused_test = np.asarray(fusion_model.predict(fusion_test.to_numpy(dtype=float)), dtype=float).reshape(-1)\n'
    '\n'
    '    payload = {\n'
    '        "model": fusion_model,\n'
    '        "train_aux_feature_columns": list(train_aux.columns),\n'
    '        "auxiliary_columns": list(aux_columns),\n'
    '        "label": str(label) if label is not None else "",\n'
    '    }\n'
    '    return fused_train, fused_test, payload\n'
    '\n'
    'def apply_auxiliary_fusion_head(base_predictions, aux_feature_df, fusion_payload):\n'
    '    if not fusion_payload:\n'
    '        return np.asarray(base_predictions, dtype=float).reshape(-1)\n'
    '    model = fusion_payload.get("model")\n'
    '    if model is None:\n'
    '        return np.asarray(base_predictions, dtype=float).reshape(-1)\n'
    '    expected_aux_columns = list(fusion_payload.get("train_aux_feature_columns", []))\n'
    '    aligned_aux = align_feature_matrix_to_training_columns(aux_feature_df.copy(), expected_aux_columns)\n'
    '    fusion_frame = pd.concat(\n'
    '        [\n'
    '            pd.DataFrame({"base_prediction": np.asarray(base_predictions, dtype=float).reshape(-1)}),\n'
    '            aligned_aux.reset_index(drop=True),\n'
    '        ],\n'
    '        axis=1,\n'
    '    )\n'
    '    return np.asarray(model.predict(fusion_frame.to_numpy(dtype=float)), dtype=float).reshape(-1)\n'
    'setup_done("auxiliary feature helper")\n'
    '\n'
    'def make_regularization_grid(min_log10=-4, max_log10=0, grid_size=40):\n'
    '    min_log10 = float(min_log10)\n'
    '    max_log10 = float(max_log10)\n'
    '    grid_size = int(grid_size)\n'
    '    if grid_size < 2:\n'
    '        raise ValueError("Regularization grid size must be at least 2.")\n'
    '    if min_log10 >= max_log10:\n'
    '        raise ValueError("Regularization grid minimum exponent must be less than the maximum exponent.")\n'
    '    return np.logspace(min_log10, max_log10, grid_size)\n'
    '\n'
    'def parse_l1_ratio_grid(l1_ratio_grid_text):\n'
    '    values = []\n'
    '    for token in str(l1_ratio_grid_text).split(","):\n'
    '        token = token.strip()\n'
    '        if not token:\n'
    '            continue\n'
    '        values.append(float(token))\n'
    '    if not values:\n'
    '        values = [0.3, 0.7, 1.0]\n'
    '    values = sorted({float(value) for value in values if 0.0 < float(value) <= 1.0})\n'
    '    if not values:\n'
    '        raise ValueError("ElasticNetCV l1_ratio values must be > 0 and <= 1.")\n'
    '    return values\n'
    '\n'
    'def select_top_coefficient_mask(coefficients, coefficient_threshold=1e-10, max_selected_features=0):\n'
    '    coefficients = np.asarray(coefficients, dtype=float)\n'
    '    abs_coefficients = np.abs(coefficients)\n'
    '    selected_mask = abs_coefficients > float(coefficient_threshold)\n'
    '    if not np.any(selected_mask):\n'
    '        strongest_index = int(np.argmax(abs_coefficients))\n'
    '        if not np.isfinite(coefficients[strongest_index]):\n'
    '            raise RuntimeError("Sparse linear feature selection did not produce any finite coefficients.")\n'
    '        selected_mask[strongest_index] = True\n'
    '    if int(max_selected_features) > 0 and int(selected_mask.sum()) > int(max_selected_features):\n'
    '        selected_indices = np.flatnonzero(selected_mask)\n'
    '        ranked_selected = selected_indices[np.argsort(abs_coefficients[selected_indices])[::-1]]\n'
    '        keep_indices = ranked_selected[: int(max_selected_features)]\n'
    '        trimmed_mask = np.zeros_like(selected_mask, dtype=bool)\n'
    '        trimmed_mask[keep_indices] = True\n'
    '        selected_mask = trimmed_mask\n'
    '    return selected_mask\n'
    '\n'
    'def apply_sparse_linear_feature_selection(\n'
    '    feature_df,\n'
    '    target_values,\n'
    '    smiles_values=None,\n'
    '    selector_method="lasso_cv",\n'
    '    alpha=1.0,\n'
    '    alpha_grid_min_log10=-5,\n'
    '    alpha_grid_max_log10=-1,\n'
    '    alpha_grid_size=12,\n'
    '    elasticnet_l1_ratio_grid="0.3, 0.7",\n'
    '    cv_split_strategy="random",\n'
    '    cv_folds=3,\n'
    '    random_seed=42,\n'
    '    coefficient_threshold=1e-10,\n'
    '    max_iter=10000,\n'
    '    selection_mode="cyclic coordinate updates",\n'
    '    max_selected_features=0,\n'
    '    progress_bar=None,\n'
    '    progress_fit_units=1,\n'
    '):\n'
    '    working_df = feature_df.copy()\n'
    '    y = np.asarray(target_values, dtype=float).reshape(-1)\n'
    '    if working_df.empty:\n'
    '        raise ValueError("Cannot run sparse linear feature selection on an empty feature matrix.")\n'
    '    selector_method = str(selector_method).strip().lower()\n'
    '    scaler = StandardScaler()\n'
    '    X_scaled = scaler.fit_transform(working_df.to_numpy(dtype=np.float32))\n'
    '    if progress_bar is not None:\n'
    '        progress_bar.set_description("Scaled feature matrix")\n'
    '        progress_bar.update(1)\n'
    '    sklearn_selection_mode = "random" if str(selection_mode).strip().lower() == "random coordinate updates" else "cyclic"\n'
    '    effective_cv_folds = None\n'
    '    selector_cv_strategy = None\n'
    '\n'
    '    if selector_method == "fixed_lasso":\n'
    '        selector = Lasso(\n'
    '            alpha=float(alpha),\n'
    '            max_iter=int(max_iter),\n'
    '            random_state=int(random_seed),\n'
    '            selection=sklearn_selection_mode,\n'
    '        )\n'
    '    elif selector_method == "lasso_cv":\n'
    '        selector_cv, effective_cv_folds, selector_cv_strategy = make_qsar_cv_splitter(\n'
    '            working_df,\n'
    '            y,\n'
    '            smiles_values if smiles_values is not None else pd.Series([""] * len(working_df)),\n'
    '            split_strategy=cv_split_strategy,\n'
    '            cv_folds=cv_folds,\n'
    '            random_seed=random_seed,\n'
    '        )\n'
    '        selector = LassoCV(\n'
    '            alphas=make_regularization_grid(alpha_grid_min_log10, alpha_grid_max_log10, alpha_grid_size),\n'
    '            cv=selector_cv,\n'
    '            max_iter=int(max_iter),\n'
    '            n_jobs=-1,\n'
    '            random_state=int(random_seed),\n'
    '            selection=sklearn_selection_mode,\n'
    '        )\n'
    '    elif selector_method == "elasticnet_cv":\n'
    '        selector_cv, effective_cv_folds, selector_cv_strategy = make_qsar_cv_splitter(\n'
    '            working_df,\n'
    '            y,\n'
    '            smiles_values if smiles_values is not None else pd.Series([""] * len(working_df)),\n'
    '            split_strategy=cv_split_strategy,\n'
    '            cv_folds=cv_folds,\n'
    '            random_seed=random_seed,\n'
    '        )\n'
    '        selector = ElasticNetCV(\n'
    '            l1_ratio=parse_l1_ratio_grid(elasticnet_l1_ratio_grid),\n'
    '            alphas=make_regularization_grid(alpha_grid_min_log10, alpha_grid_max_log10, alpha_grid_size),\n'
    '            cv=selector_cv,\n'
    '            max_iter=int(max_iter),\n'
    '            n_jobs=-1,\n'
    '            random_state=int(random_seed),\n'
    '            selection=sklearn_selection_mode,\n'
    '        )\n'
    '    else:\n'
    '        raise ValueError("selector_method must be \'fixed_lasso\', \'lasso_cv\', or \'elasticnet_cv\'.")\n'
    '\n'
    '    if progress_bar is not None:\n'
    '        progress_bar.set_description(f"Fitting {selector_method}")\n'
    '        progress_bar.update(1)\n'
    '    elapsed_event = None\n'
    '    elapsed_thread = None\n'
    '    if progress_bar is not None and selector_method in {"lasso_cv", "elasticnet_cv"}:\n'
    '        import threading\n'
    '        import time as _time\n'
    '\n'
    '        elapsed_event = threading.Event()\n'
    '\n'
    '        def _elapsed_updater():\n'
    '            start = _time.perf_counter()\n'
    '            while not elapsed_event.is_set():\n'
    '                _time.sleep(2.0)\n'
    '                elapsed = _time.perf_counter() - start\n'
    '                progress_bar.set_postfix_str(f"elapsed {elapsed/60.0:.1f} min")\n'
    '\n'
    '        elapsed_thread = threading.Thread(target=_elapsed_updater, daemon=True)\n'
    '        elapsed_thread.start()\n'
    '    selector.fit(X_scaled, y)\n'
    '    if elapsed_event is not None:\n'
    '        elapsed_event.set()\n'
    '        if elapsed_thread is not None:\n'
    '            elapsed_thread.join(timeout=1.0)\n'
    '    if progress_bar is not None:\n'
    '        progress_bar.update(max(1, int(progress_fit_units)))\n'
    '        progress_bar.set_description("Selecting nonzero coefficients")\n'
    '    coefficients = np.asarray(selector.coef_, dtype=float)\n'
    '    selected_mask = select_top_coefficient_mask(\n'
    '        coefficients,\n'
    '        coefficient_threshold=float(coefficient_threshold),\n'
    '        max_selected_features=int(max_selected_features),\n'
    '    )\n'
    '    selected_columns = working_df.columns[selected_mask].tolist()\n'
    '    trimmed_df = working_df.loc[:, selected_columns].copy()\n'
    '    if progress_bar is not None:\n'
    '        progress_bar.update(1)\n'
    '        progress_bar.set_description("Building diagnostics")\n'
    '    abs_coefficients = np.abs(coefficients)\n'
    '    diagnostic_df = pd.DataFrame(\n'
    '        {\n'
    '            "feature": working_df.columns.astype(str),\n'
    '            "coefficient": coefficients,\n'
    '            "abs_coefficient": abs_coefficients,\n'
    '            "selected": selected_mask,\n'
    '        }\n'
    '    ).sort_values("abs_coefficient", ascending=False).reset_index(drop=True)\n'
    '    cv_diagnostics_df = pd.DataFrame()\n'
    '    best_cv_rmse = None\n'
    '    best_alpha_at_grid_edge = None\n'
    '    best_l1_ratio_at_grid_edge = None\n'
    '    if selector_method in {"lasso_cv", "elasticnet_cv"} and hasattr(selector, "mse_path_"):\n'
    '        mse_path = np.asarray(selector.mse_path_, dtype=float)\n'
    '        alpha_values = np.asarray(selector.alphas_, dtype=float)\n'
    '        l1_values = np.asarray(parse_l1_ratio_grid(elasticnet_l1_ratio_grid), dtype=float)\n'
    '        rows = []\n'
    '        if selector_method == "elasticnet_cv" and mse_path.ndim == 3:\n'
    '            for l1_index, l1_value in enumerate(l1_values):\n'
    '                for alpha_index, alpha_value in enumerate(alpha_values):\n'
    '                    fold_mse = np.asarray(mse_path[l1_index, alpha_index, :], dtype=float)\n'
    '                    rows.append(\n'
    '                        {\n'
    '                            "alpha": float(alpha_value),\n'
    '                            "l1_ratio": float(l1_value),\n'
    '                            "mean_cv_mse": float(np.nanmean(fold_mse)),\n'
    '                            "std_cv_mse": float(np.nanstd(fold_mse)),\n'
    '                            "mean_cv_rmse": float(np.sqrt(np.nanmean(fold_mse))),\n'
    '                        }\n'
    '                    )\n'
    '        elif mse_path.ndim == 2:\n'
    '            for alpha_index, alpha_value in enumerate(alpha_values):\n'
    '                fold_mse = np.asarray(mse_path[alpha_index, :], dtype=float)\n'
    '                rows.append(\n'
    '                    {\n'
    '                        "alpha": float(alpha_value),\n'
    '                        "l1_ratio": None,\n'
    '                        "mean_cv_mse": float(np.nanmean(fold_mse)),\n'
    '                        "std_cv_mse": float(np.nanstd(fold_mse)),\n'
    '                        "mean_cv_rmse": float(np.sqrt(np.nanmean(fold_mse))),\n'
    '                    }\n'
    '                )\n'
    '        if rows:\n'
    '            cv_diagnostics_df = pd.DataFrame(rows).sort_values("mean_cv_mse", ascending=True).reset_index(drop=True)\n'
    '            best_cv_rmse = float(cv_diagnostics_df.loc[0, "mean_cv_rmse"])\n'
    '            alpha_grid_values = np.asarray(alpha_values, dtype=float).reshape(-1)\n'
    '            best_alpha = float(getattr(selector, "alpha_", float(alpha)))\n'
    '            best_alpha_at_grid_edge = bool(\n'
    '                np.isclose(best_alpha, float(np.nanmin(alpha_grid_values)))\n'
    '                or np.isclose(best_alpha, float(np.nanmax(alpha_grid_values)))\n'
    '            )\n'
    '            if selector_method == "elasticnet_cv":\n'
    '                best_l1 = float(getattr(selector, "l1_ratio_", np.nan))\n'
    '                best_l1_ratio_at_grid_edge = bool(\n'
    '                    np.isfinite(best_l1)\n'
    '                    and (\n'
    '                        np.isclose(best_l1, float(np.nanmin(l1_values)))\n'
    '                        or np.isclose(best_l1, float(np.nanmax(l1_values)))\n'
    '                    )\n'
    '                )\n'
    '    summary = {\n'
    '        "selector_method": selector_method,\n'
    '        "selected_columns": list(selected_columns),\n'
    '        "selected_feature_count": int(len(selected_columns)),\n'
    '        "original_feature_count": int(working_df.shape[1]),\n'
    '        "alpha": float(getattr(selector, "alpha_", getattr(selector, "alpha", float(alpha)))),\n'
    '        "l1_ratio": (\n'
    '            float(getattr(selector, "l1_ratio_"))\n'
    '            if hasattr(selector, "l1_ratio_")\n'
    '            else getattr(selector, "l1_ratio", None)\n'
    '        ),\n'
    '        "coefficient_threshold": float(coefficient_threshold),\n'
    '        "max_iter": int(max_iter),\n'
    '        "selection_mode": str(selection_mode),\n'
    '        "max_selected_features": int(max_selected_features),\n'
    '        "cv_folds": int(effective_cv_folds) if effective_cv_folds is not None else None,\n'
    '        "cv_split_strategy": selector_cv_strategy if selector_method in {"lasso_cv", "elasticnet_cv"} else None,\n'
    '        "n_iter": int(np.max(np.atleast_1d(getattr(selector, "n_iter_", 0)))),\n'
    '        "training_r2_on_scaled_features": float(selector.score(X_scaled, y)),\n'
    '        "intercept": float(np.ravel(np.atleast_1d(selector.intercept_))[0]),\n'
    '        "top_coefficients": diagnostic_df.head(50).copy(),\n'
    '        "cv_diagnostics": cv_diagnostics_df.head(50).copy(),\n'
    '        "best_cv_rmse": best_cv_rmse,\n'
    '        "best_alpha_at_grid_edge": best_alpha_at_grid_edge,\n'
    '        "best_l1_ratio_at_grid_edge": best_l1_ratio_at_grid_edge,\n'
    '    }\n'
    '    if progress_bar is not None:\n'
    '        progress_bar.update(1)\n'
