    'setup_done("feature builder helper")\n'
    '\n'
    'setup_start("regression summary helper")\n'
    'def summarize_regression(y_true, y_pred, prefix):\n'
    '    series_true = pd.Series(y_true, dtype=float)\n'
    '    series_pred = pd.Series(y_pred, dtype=float)\n'
    '    spearman = series_true.corr(series_pred, method="spearman")\n'
    '    if pd.isna(spearman):\n'
    '        spearman = np.nan\n'
    '    return {\n'
    '        f"{prefix} R2": float(r2_score(y_true, y_pred)),\n'
    '        f"{prefix} RMSE": float(math.sqrt(mean_squared_error(y_true, y_pred))),\n'
    '        f"{prefix} MAE": float(mean_absolute_error(y_true, y_pred)),\n'
    '        f"{prefix} Spearman": float(spearman),\n'
