    'def _refit_train_only_selector(X_fit, y_fit, smiles_fit):\n'
    '    # Repeat the train-only selector on a subset of training rows (used for nested CV in 4C and 7A).\n'
    '    X_fit = pd.DataFrame(X_fit).reset_index(drop=True)\n'
    '    y_fit = np.asarray(y_fit, dtype=float).reshape(-1)\n'
    '    if train_selector_method in {"fixed_lasso", "lasso_cv", "elasticnet_cv"}:\n'
    '        _, fold_details = apply_sparse_linear_feature_selection(\n'
    '            feature_df=X_fit,\n'
    '            target_values=y_fit,\n'
    '            selector_method=train_selector_method,\n'
    '            alpha=float(feature_selection_config.get("fixed_lasso_alpha", 1.0)),\n'
    '            alpha_grid_min_log10=float(feature_selection_config.get("alpha_grid_min_log10", -5)),\n'
    '            alpha_grid_max_log10=float(feature_selection_config.get("alpha_grid_max_log10", -1)),\n'
    '            alpha_grid_size=int(feature_selection_config.get("alpha_grid_size", 12)),\n'
    '            elasticnet_l1_ratio_grid=str(feature_selection_config.get("elasticnet_l1_ratio_grid", "0.3, 0.7")),\n'
    '            cv_split_strategy=selector_cv_split_strategy,\n'
    '            cv_folds=int(feature_selection_config.get("cv_folds", 3)),\n'
    '            random_seed=int(model_random_seed),\n'
    '            coefficient_threshold=float(feature_selection_config.get("coefficient_threshold", 1e-10)),\n'
