    '        if resume_state is not None:\n'
    '            ga.population = list(resume_state["population"])\n'
    '            ga.fitness_dict = dict(resume_state["fitness_dict"])\n'
    '            resumed_model_work = min(\n'
    '                per_model_expected_work,\n'
    '                per_model_init_work + resume_generation_offset * per_model_generation_work,\n'
    '            )\n'
    '            if resumed_model_work > 0:\n'
    '                tuning_progress.update(resumed_model_work)\n'
    '                progress_state["overall_completed_work"] += resumed_model_work\n'
    '                progress_state["model_completed_work"] += resumed_model_work\n'
    '                overall_completed_work = progress_state["overall_completed_work"]\n'
    '                model_completed_work = progress_state["model_completed_work"]\n'
    '            if resume_generation_offset > 0:\n'
    '                generation_progress.update(resume_generation_offset)\n'
