    '\n'
    '        def ga_progress_callback(payload, _model_name=model_name):\n'
    '            event = payload.get("event", "generation_complete")\n'
    '            completed = resume_generation_offset + int(payload.get("generation", 0))\n'
    '            total = int(ga_generations)\n'
    '            if generation_progress.total != total:\n'
    '                generation_progress.total = total\n'
    '\n'
    '            def sync_outer_progress(target_model_work, status_text):\n'
    '                target_model_work = max(0, min(int(target_model_work), per_model_expected_work))\n'
    '                delta = target_model_work - progress_state["model_completed_work"]\n'
    '                if delta > 0:\n'
    '                    tuning_progress.update(delta)\n'
    '                    progress_state["overall_completed_work"] += delta\n'
    '                    progress_state["model_completed_work"] += delta\n'
    '                tuning_progress.set_postfix_str(\n'
    '                    f"{status_text} | overall {progress_state[\'overall_completed_work\']}/{total_expected_work} work"\n'
    '                )\n'
    '\n'
    '            if event == "generation_start":\n'
    '                expected = max(1, int(payload.get("expected_generation_evaluations", int(ga_crossover_size) + int(ga_mutation_size))))\n'
    '                evaluation_progress.reset(total=expected)\n'
    '                evaluation_progress.set_description(f"{_model_name} generation {completed}")\n'
    '                evaluation_progress.set_postfix_str("starting")\n'
    '                sync_outer_progress(\n'
    '                    per_model_init_work + max(0, completed - 1) * per_model_generation_work,\n'
    '                    f"{_model_name} (generation {completed}/{total})",\n'
    '                )\n'
    '                return\n'
    '            if event == "evaluation":\n'
