    '                stage = str(payload.get("stage", "evaluation"))\n'
    '                if completed == 0:\n'
    '                    if evaluation_progress.total != int(ga_population_size):\n'
    '                        evaluation_progress.reset(total=int(ga_population_size))\n'
    '                        evaluation_progress.set_description(f"{_model_name} initialization")\n'
    '                    evaluation_progress.set_postfix_str(stage)\n'
    '                else:\n'
    '                    if evaluation_progress.total != expected:\n'
    '                        evaluation_progress.reset(total=expected)\n'
    '                        evaluation_progress.set_description(f"{_model_name} generation {completed}")\n'
    '                    evaluation_progress.set_postfix_str(stage)\n'
    '                generation_eval_completed = int(payload.get("generation_evaluations_completed", 0))\n'
