    '\n'
    '    api_key = _tabpfn_api_key_present()\n'
    '    result["api_key_present"] = bool(api_key)\n'
    '    if api_key:\n'
    '        token_ok, token_error = _apply_tabpfn_access_token(api_key)\n'
    '        result["access_token_set_ok"] = bool(token_ok)\n'
    '        result["access_token_set_error"] = str(token_error or "")\n'
    '\n'
    '    try:\n'
    '        probe_model = make_tabpfn_regressor()\n'
