    '\n'
    '    STATE["tabpfn_auth"] = dict(result)\n'
    '    STATE["tabpfn_preflight_ok"] = bool(result.get("tabpfn_preflight_ok", False))\n'
    '    return result\n'
    '\n'
    'def _display_tabpfn_auth_result(result):\n'
    '    if result.get("tabpfn_preflight_ok"):\n'
