    '    if result.get("access_token_set_error"):\n'
    '        summary_lines.append(f"tabpfn_client.set_access_token failed: {result[\'access_token_set_error\']}")\n'
    '    if result.get("tabpfn_preflight_error"):\n'
    '        summary_lines.append(f"TabPFN preflight error: {result[\'tabpfn_preflight_error\']}")\n'
