    '\n'
    'if widgets is not None:\n'
    '    api_key_widget = widgets.Password(\n'
    '        description="PRIORLABS_API_KEY",\n'
    '        placeholder="paste key",\n'
    '        layout=widgets.Layout(width="520px"),\n'
    '    )\n'
    '    apply_button = widgets.Button(\n'
    '        description="Set key + test TabPFN",\n'
    '        button_style="primary",\n'
    '        tooltip="Store API key in environment and run TabPFN preflight",\n'
    '    )\n'
    '    clear_button = widgets.Button(\n'
    '        description="Clear key",\n'
    '        button_style="warning",\n'
    '        tooltip="Remove PRIORLABS_API_KEY from this kernel session",\n'
    '    )\n'
    '    auth_output = widgets.Output()\n'
    '\n'
    '    def _handle_apply(_):\n'
    '        api_key = str(api_key_widget.value or "").strip()\n'
    '        if api_key:\n'
    '            _apply_tabpfn_access_token(api_key)\n'
    '        api_key_widget.value = ""\n'
    '        result = _run_tabpfn_auth_check()\n'
    '        with auth_output:\n'
    '            clear_output(wait=True)\n'
    '            _display_tabpfn_auth_result(result)\n'
    '\n'
    '    def _handle_clear(_):\n'
    '        os.environ.pop("PRIORLABS_API_KEY", None)\n'
