    '\n'
    'def _patch_torchdata_dill_available():\n'
    '    try:\n'
    '        import torch.utils.data.datapipes.utils.common as _torch_datapipe_common\n'
    '\n'
    '        if not hasattr(_torch_datapipe_common, "DILL_AVAILABLE"):\n'
    '            _torch_datapipe_common.DILL_AVAILABLE = False\n'
