    'def ensure_maplight_graphbolt_compatibility():\n'
    '    if IN_COLAB:\n'
    '        return\n'
    '\n'
    '    def _run_pip_repair(attempts, failure_message):\n'
    '        failed_attempts = []\n'
    '        for attempt_label, attempt_cmd in attempts:\n'
    '            print(f"[MapLight fix] Attempting install via {attempt_label}...", flush=True)\n'
    '            result = subprocess.run(attempt_cmd, capture_output=True, text=True)\n'
    '            if result.returncode == 0:\n'
    '                print(f"[MapLight fix] Install succeeded via {attempt_label}.", flush=True)\n'
    '                return True\n'
    '            failure_text = ((result.stdout or "") + "\\n" + (result.stderr or "")).strip()\n'
    '            failed_attempts.append((attempt_label, result.returncode, failure_text[-1200:]))\n'
    '            print(\n'
    '                f"[MapLight fix] Install attempt failed via {attempt_label} (exit code {result.returncode}).",\n'
    '                flush=True,\n'
    '            )\n'
    '\n'
    '        failure_summary = "; ".join(\n'
    '            [f"{label} exit={code}" for label, code, _ in failed_attempts]\n'
    '        )\n'
    '        last_logs = failed_attempts[-1][2] if failed_attempts else ""\n'
    '        raise RuntimeError(\n'
    '            f"{failure_message} Automatic attempts failed ({failure_summary}).\\n\\n"\n'
    '            "Last pip output snippet:\\n"\n'
    '            f"{last_logs}"\n'
    '        )\n'
    '\n'
    '    def _torchdata_datapipes_check():\n'
    '        result = subprocess.run(\n'
    '            [\n'
    '                sys.executable,\n'
    '                "-c",\n'
    '                "import torch.utils.data.datapipes.utils.common as _c; "\n'
    '                "_c.DILL_AVAILABLE = getattr(_c, \'DILL_AVAILABLE\', False); "\n'
    '                "from torchdata import datapipes as _dp; print(\'torchdata_datapipes_ok\')",\n'
    '            ],\n'
    '            capture_output=True,\n'
    '            text=True,\n'
    '        )\n'
    '        logs = ((result.stdout or "") + "\\n" + (result.stderr or "")).strip()\n'
    '        return result.returncode == 0, logs[-1200:]\n'
    '\n'
    '    dgl_spec = importlib.util.find_spec("dgl")\n'
    '    if dgl_spec is None or not getattr(dgl_spec, "origin", None):\n'
    '        return\n'
    '    dgl_root = Path(dgl_spec.origin).resolve().parent\n'
    '    graphbolt_dir = dgl_root / "graphbolt"\n'
    '    if not graphbolt_dir.exists():\n'
    '        return\n'
    '\n'
    '    if sys.platform.startswith("win"):\n'
    '        graphbolt_pattern = "graphbolt_pytorch_*.dll"\n'
    '        graphbolt_regex = re.compile(r"^graphbolt_pytorch_([0-9]+[.][0-9]+[.][0-9]+)[.]dll$")\n'
    '    elif sys.platform.startswith("linux"):\n'
    '        graphbolt_pattern = "libgraphbolt_pytorch_*.so"\n'
    '        graphbolt_regex = re.compile(r"^libgraphbolt_pytorch_([0-9]+[.][0-9]+[.][0-9]+)[.]so$")\n'
    '    elif sys.platform.startswith("darwin"):\n'
    '        graphbolt_pattern = "libgraphbolt_pytorch_*.dylib"\n'
    '        graphbolt_regex = re.compile(r"^libgraphbolt_pytorch_([0-9]+[.][0-9]+[.][0-9]+)[.]dylib$")\n'
    '    else:\n'
    '        return\n'
    '\n'
    '    available_versions = []\n'
    '    for path in graphbolt_dir.glob(graphbolt_pattern):\n'
    '        match = graphbolt_regex.match(path.name)\n'
    '        if match:\n'
    '            available_versions.append(match.group(1))\n'
    '    if not available_versions:\n'
    '        return\n'
    '    available_versions = sorted(set(available_versions), key=_version_key)\n'
    '\n'
    '    repaired_components = []\n'
    '\n'
    '    torch_version = ""\n'
    '    if torch is not None:\n'
    '        torch_version = str(getattr(torch, "__version__", "") or "")\n'
    '    if not torch_version:\n'
    '        try:\n'
    '            import importlib.metadata as _importlib_metadata\n'
    '\n'
    '            torch_version = str(_importlib_metadata.version("torch"))\n'
    '        except Exception:\n'
    '            return\n'
    '    torch_base = torch_version.split("+", 1)[0]\n'
    '    _torch_is_cuda_build = "+cu" in torch_version.lower()\n'
