    '                flush=True,\n'
    '            )\n'
    '        else:\n'
    '            target_torch = available_versions[-1]\n'
    '            print(\n'
    '                "MapLight + GNN compatibility check: "\n'
    '                f"installed torch={torch_base}, but DGL provides GraphBolt binaries for {available_versions}.",\n'
    '                flush=True,\n'
    '            )\n'
    '            print(\n'
    '                "Installing a CPU PyTorch build compatible with installed DGL: "\n'
    '                f"torch=={target_torch}",\n'
    '                flush=True,\n'
    '            )\n'
    '\n'
    '            install_attempts = [\n'
    '                (\n'
    '                    "PyTorch CPU index (no deps)",\n'
    '                    [\n'
