    '            )\n'
    '\n'
    '    if repaired_components:\n'
    '        raise RuntimeError(\n'
    '            "Installed/updated MapLight + GNN compatibility dependencies "\n'
    '            f"({\', \'.join(repaired_components)}). "\n'
    '            "Restart the kernel, rerun step 0, then rerun block 5B."\n'
    '        )\n'
    '\n'
    'maplight_gnn_available = True\n'
    'if run_maplight_gnn:\n'
    '    if not IN_COLAB:\n'
    '        ensure_maplight_graphbolt_compatibility()\n'
    '    try:\n'
    '        from molfeat.trans.pretrained import PretrainedDGLTransformer\n'
