    '\n'
    'def _is_maplight_store_access_error(exc):\n'
    '    message = str(exc).lower()\n'
    '    markers = [\n'
    '        "molfeat-store-prod",\n'
    '        "storage.objects.list",\n'
    '        "anonymous caller",\n'
    '        "default credentials",\n'
    '        "httperror",\n'
    '        "cannot connect to host storage.googleapis.com",\n'
    '    ]\n'
    '    return any(marker in message for marker in markers)\n'
    '\n'
    'def _build_maplight_gnn_embedder(kind="gin_supervised_masking"):\n'
    '    _patch_torchdata_dill_available()\n'
    '    from molfeat.trans.pretrained import PretrainedDGLTransformer\n'
    '\n'
    '    try:\n'
    '        transformer = PretrainedDGLTransformer(kind=kind, dtype=float)\n'
    '\n'
    '        def _embed_with_molfeat(smiles_values):\n'
    '            return transformer(smiles_values)\n'
    '\n'
    '        return _embed_with_molfeat, "molfeat-store"\n'
    '    except Exception as primary_exc:\n'
    '        if not _is_maplight_store_access_error(primary_exc):\n'
    '            raise\n'
    '        try:\n'
    '            import dgl\n'
    '            import dgllife\n'
    '            import torch\n'
    '            from torch.utils.data import DataLoader\n'
    '\n'
    '            pretrained_cache_dir = resolve_output_path("model_cache/maplight_gnn_pretrained")\n'
    '            pretrained_cache_dir.mkdir(parents=True, exist_ok=True)\n'
    '            cache_filename = f"{kind}_pre_trained.pth"\n'
    '            env_download_dir = str(os.environ.get("DGL_DOWNLOAD_DIR", "")).strip()\n'
    '            if env_download_dir:\n'
    '                candidate_env_cache = Path(env_download_dir).expanduser() / cache_filename\n'
    '                if candidate_env_cache.exists():\n'
    '                    pretrained_cache_dir = candidate_env_cache.parent\n'
    '            os.environ["DGL_DOWNLOAD_DIR"] = str(pretrained_cache_dir.resolve())\n'
    '            cached_weight_file = pretrained_cache_dir / cache_filename\n'
    '            if cached_weight_file.exists():\n'
    '                print(\n'
    '                    f"MapLight + GNN note: reusing cached pretrained weights at {cached_weight_file}.",\n'
    '                    flush=True,\n'
    '                )\n'
    '            fallback_model = None\n'
    '            if cached_weight_file.exists():\n'
    '                try:\n'
    '                    from dgllife.model.pretrain import create_property_model\n'
    '\n'
    '                    fallback_model = create_property_model(kind)\n'
    '                    if fallback_model is None:\n'
    '                        raise ValueError(f"dgllife has no direct property-model constructor for kind={kind}")\n'
    '                    checkpoint = torch.load(str(cached_weight_file), map_location="cpu")\n'
    '                    try:\n'
    '                        fallback_model.load_state_dict(checkpoint["model_state_dict"])\n'
    '                    except Exception:\n'
    '                        fallback_model.load_state_dict(checkpoint)\n'
    '                except Exception as cache_exc:\n'
    '                    fallback_model = None\n'
    '                    print(\n'
    '                        f"MapLight + GNN note: cached pretrained weights could not be loaded directly ({cache_exc}); "\n'
    '                        "falling back to dgllife loader.",\n'
    '                        flush=True,\n'
    '                    )\n'
