    '            raise RuntimeError("No trained models are available yet. Train at least one model before running prediction.")\n'
    '        candidate_df = pd.DataFrame(candidates)\n'
    '        validated = candidate_df[np.isfinite(candidate_df["validation_rmse"])]\n'
    '        if not validated.empty:\n'
    '            best = validated.sort_values("validation_rmse").iloc[0]\n'
    '            skipped = sorted(set(candidate_df.loc[~np.isfinite(candidate_df["validation_rmse"]), "model"]))\n'
    '            _shown = (lambda loss: 1.0 - loss) if _cls_choice else (lambda loss: loss)\n'
    '            print(\n'
    '                f"Best available: {best[\'model\']} ({best[\'workflow\']}), chosen by {best[\'validation_label\']} = "\n'
    '                f"{_shown(best[\'validation_rmse\']):.4f} on the training split. Its test {_choice_metric} "\n'
    '                f"({_shown(best[\'test_rmse\']):.4f}) was not used to choose it, so it is an honest estimate."\n'
    '            )\n'
    '            if skipped:\n'
    '                print(\n'
    '                    "Not eligible (no CV/OOF score): " + ", ".join(skipped)\n'
    '                    + ". Name one in prediction_model_name to use it anyway."\n'
    '                )\n'
    '        else:\n'
    '            best = candidate_df.sort_values("test_rmse").iloc[0]\n'
    '            print(\n'
    '                f"Best available: {best[\'model\']} ({best[\'workflow\']}), chosen by test {_choice_metric} "\n'
    '                f"(loss {best[\'test_rmse\']:.4f}) "\n'
    '                "because no model has a CV or OOF score. That test score is optimistic: turn on cross-validation "\n'
    '                "in 4C for an honest choice."\n'
    '            )\n'
    '        STATE["prediction_model_selection"] = {\n'
    '            "workflow": str(best["workflow"]),\n'
    '            "model": str(best["model"]),\n'
    '            "criterion": (str(best["validation_label"]) if not validated.empty else "Test RMSE (no CV/OOF score available)"),\n'
    '            "criterion_value": float(best["validation_rmse"] if not validated.empty else best["test_rmse"]),\n'
    '            "test_rmse": float(best["test_rmse"]) if np.isfinite(best["test_rmse"]) else None,\n'
    '            "candidates_considered": int(len(candidate_df)),\n'
