    '\n'
    '        def _coerce_string_list(values):\n'
    '            if isinstance(values, (list, tuple, set)):\n'
    '                output = []\n'
    '                for value in values:\n'
    '                    text = str(value).strip()\n'
    '                    if text:\n'
