    '\n'
    '        def _align_predictions_by_smiles_occurrence(expected_smiles, actual_smiles, pred_values):\n'
    '            expected_df = pd.DataFrame({"smiles": pd.Series(expected_smiles, dtype=str).str.strip()})\n'
    '            actual_df = pd.DataFrame(\n'
    '                {\n'
    '                    "smiles": pd.Series(actual_smiles, dtype=str).str.strip(),\n'
