    '                }\n'
    '            )\n'
    '            expected_df["_occurrence"] = expected_df.groupby("smiles", sort=False).cumcount()\n'
    '            expected_df["_expected_row"] = np.arange(len(expected_df), dtype=int)\n'
    '            actual_df["_occurrence"] = actual_df.groupby("smiles", sort=False).cumcount()\n'
